/* C evaluation fixture for the bounded polyhedral optimizer. */
long kernel(long seed){double a[961],b[961],c[961];for(long i=0;i<31;i++)for(long j=0;j<31;j++){a[i*31+j]=(i+j+seed)&15;b[i*31+j]=(i*3+j)&7;c[i*31+j]=0;}for(long i=0;i<31;i++)for(long j=0;j<31;j++)for(long k=0;k<31;k++)c[i*31+j]+=a[i*31+k]*b[j*31+k];long sum=0;for(long i=0;i<31;i++)for(long j=0;j<31;j++)sum+=(long)c[i*31+j]*(i+j+1);return sum;}
